using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using TabulariusAI.Web.Data;
using TabulariusAI.Web.Data.Entities;
using TabulariusAI.Web.Models;
using TabulariusAI.Web.Services;
namespace TabulariusAI.Web.Controllers;
public sealed partial class DossierController(TabulariusDbContext dbContext):Controller
{
 private static readonly int[] AllowedPageSizes=[10,25,50,100];
 public async Task<IActionResult> Entities(string? search,int page=1,int pageSize=10,CancellationToken cancellationToken=default){var q=dbContext.AccountingEntities.AsNoTracking().Include(x=>x.Dossiers).AsQueryable();if(!string.IsNullOrWhiteSpace(search)){var t=search.Trim();q=q.Where(x=>x.Name.Contains(t)||x.TaxRegistrationNumber.Contains(t));}return View(await PageAsync(q.OrderBy(x=>x.Name),search,page,pageSize,cancellationToken));}
 public async Task<IActionResult> Entity(int id,string? search,int page=1,int pageSize=10,CancellationToken cancellationToken=default){var e=await dbContext.AccountingEntities.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,cancellationToken);if(e is null)return NotFound();var q=dbContext.AnalysisDossiers.AsNoTracking().Include(x=>x.Imports).Where(x=>x.AccountingEntityId==id);if(!string.IsNullOrWhiteSpace(search)){var t=search.Trim();q=q.Where(x=>x.Name.Contains(t)||x.FiscalYear.ToString().Contains(t));}return View(new EntityDossiersViewModel{Entity=e,List=await PageAsync(q.OrderByDescending(x=>x.FiscalYear).ThenBy(x=>x.Name),search,page,pageSize,cancellationToken)});}
 public async Task<IActionResult> Details(int id,CancellationToken ct){var d=await LoadDossierAsync(id,ct);return d is null?NotFound():View(d);}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteEntity(int id,CancellationToken ct){var e=await dbContext.AccountingEntities.SingleOrDefaultAsync(x=>x.Id==id,ct);if(e is null)return NotFound();dbContext.AccountingEntities.Remove(e);await dbContext.SaveChangesAsync(ct);TempData["SuccessMessage"]="A entidade e todos os respetivos dossiers e dados importados foram eliminados.";return RedirectToAction(nameof(Entities));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteDossier(int id,CancellationToken ct){var d=await dbContext.AnalysisDossiers.SingleOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();var eid=d.AccountingEntityId;dbContext.AnalysisDossiers.Remove(d);await dbContext.SaveChangesAsync(ct);TempData["SuccessMessage"]="O dossier e todas as respetivas importações foram eliminados.";return RedirectToAction(nameof(Entity),new{id=eid});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteImport(int id,CancellationToken ct){var i=await dbContext.SaftImports.SingleOrDefaultAsync(x=>x.Id==id,ct);if(i is null)return NotFound();var did=i.DossierId;dbContext.SaftImports.Remove(i);await dbContext.SaveChangesAsync(ct);TempData["SuccessMessage"]="A importação SAF-T (PT) e os respetivos dados foram eliminados.";return RedirectToAction(nameof(Details),new{id=did});}
 public async Task<IActionResult> SaftSummary(int id,int? importId,CancellationToken ct)=>await ImportViewAsync(id,importId,ct,q=>q.Include(x=>x.Accounts).Include(x=>x.Customers).Include(x=>x.Suppliers).Include(x=>x.Products));
 public async Task<IActionResult> Accounts(int id,int? importId,string? search,int page=1,int pageSize=10,CancellationToken ct=default)=>await ListAsync(id,importId,search,page,pageSize,ct,dbContext.SaftAccounts.AsNoTracking(),x=>x.AccountId,x=>x.AccountId.Contains(search??"")||x.Description.Contains(search??""));
 public async Task<IActionResult> Customers(int id,int? importId,string? search,int page=1,int pageSize=10,CancellationToken ct=default)=>await ListAsync(id,importId,search,page,pageSize,ct,dbContext.SaftCustomers.AsNoTracking(),x=>x.CompanyName,x=>x.CustomerId.Contains(search??"")||x.CompanyName.Contains(search??"")||x.TaxId.Contains(search??""));
 public async Task<IActionResult> Suppliers(int id,int? importId,string? search,int page=1,int pageSize=10,CancellationToken ct=default)=>await ListAsync(id,importId,search,page,pageSize,ct,dbContext.SaftSuppliers.AsNoTracking(),x=>x.CompanyName,x=>x.SupplierId.Contains(search??"")||x.CompanyName.Contains(search??"")||x.TaxId.Contains(search??""));
 public async Task<IActionResult> Products(int id,int? importId,string? search,int page=1,int pageSize=10,CancellationToken ct=default)=>await ListAsync(id,importId,search,page,pageSize,ct,dbContext.SaftProducts.AsNoTracking(),x=>x.ProductDescription,x=>x.ProductCode.Contains(search??"")||x.ProductDescription.Contains(search??""));
 public async Task<IActionResult> AccountingEntries(int id,int? importId,string? search,int page=1,int pageSize=10,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var q=dbContext.SaftTransactions.AsNoTracking().Where(x=>x.SaftImportId==s.SelectedImport.Id);if(!string.IsNullOrWhiteSpace(search)){var t=search.Trim();q=q.Where(x=>x.TransactionId.Contains(t)||x.Description.Contains(t)||x.JournalId.Contains(t));}return View(new SaftListViewModel<SaftTransaction>{Source=s,List=await PageAsync(q.OrderByDescending(x=>x.TransactionDate),search,page,pageSize,ct)});}
 public async Task<IActionResult> AccountingEntry(int id,int importId,int transactionId,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var x=await dbContext.SaftTransactions.AsNoTracking().Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==transactionId&&x.SaftImportId==s.SelectedImport.Id,ct);return x is null?NotFound():View(new SaftEntryDetailViewModel{Source=s,Transaction=x});}
 public async Task<IActionResult> WorkingDocuments(int id,int? importId,string? search,int page=1,int pageSize=10,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var q=dbContext.SaftWorkingDocuments.AsNoTracking().Where(x=>x.SaftImportId==s.SelectedImport.Id);if(!string.IsNullOrWhiteSpace(search)){var t=search.Trim();q=q.Where(x=>x.DocumentNumber.Contains(t)||x.WorkType.Contains(t)||x.SourceId.Contains(t)||(x.CustomerId!=null&&x.CustomerId.Contains(t)));}return View(new SaftListViewModel<SaftWorkingDocument>{Source=s,List=await PageAsync(q.OrderByDescending(x=>x.WorkDate).ThenBy(x=>x.DocumentNumber),search,page,pageSize,ct)});}
 public async Task<IActionResult> WorkingDocument(int id,int importId,int documentId,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var d=await dbContext.SaftWorkingDocuments.AsNoTracking().Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==documentId&&x.SaftImportId==s.SelectedImport.Id,ct);return d is null?NotFound():View(new SaftWorkingDocumentDetailViewModel{Source=s,Document=d});}
 public async Task<IActionResult> TrialBalance(int id,int? importId,string? search,bool includeZeroAccounts=false,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var a=await dbContext.SaftAccounts.AsNoTracking().Where(x=>x.SaftImportId==s.SelectedImport.Id).ToListAsync(ct);var l=await dbContext.SaftTransactionLines.AsNoTracking().Where(x=>x.SaftTransaction.SaftImportId==s.SelectedImport.Id).ToListAsync(ct);var rows=TrialBalanceCalculator.Calculate(a,l).AsEnumerable();if(!includeZeroAccounts)rows=rows.Where(x=>x.OpeningDebit!=0||x.OpeningCredit!=0||x.DebitMovements!=0||x.CreditMovements!=0||x.ReportedClosingDebit!=0||x.ReportedClosingCredit!=0);if(!string.IsNullOrWhiteSpace(search)){var t=search.Trim();rows=rows.Where(x=>x.AccountId.Contains(t,StringComparison.OrdinalIgnoreCase)||x.Description.Contains(t,StringComparison.OrdinalIgnoreCase));}return View(new TrialBalanceViewModel{Source=s,Rows=rows.ToList(),Search=search?.Trim(),IncludeZeroAccounts=includeZeroAccounts});}
 public async Task<IActionResult> IncomeStatement(int id,int? importId,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var m=IncomeStatementCalculator.Calculate(await dbContext.SaftAccounts.AsNoTracking().Where(x=>x.SaftImportId==s.SelectedImport.Id).ToListAsync(ct),await dbContext.SaftTransactionLines.AsNoTracking().Where(x=>x.SaftTransaction.SaftImportId==s.SelectedImport.Id).ToListAsync(ct));m.Source=s;return View(m);}
 public async Task<IActionResult> BalanceSheet(int id,int? importId,CancellationToken ct=default){var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var m=BalanceSheetCalculator.Calculate(await dbContext.SaftAccounts.AsNoTracking().Where(x=>x.SaftImportId==s.SelectedImport.Id).ToListAsync(ct));m.Source=s;return View(m);}
 private async Task<IActionResult> ListAsync<T,TKey>(int id,int? importId,string? search,int page,int pageSize,CancellationToken ct,IQueryable<T> source,System.Linq.Expressions.Expression<Func<T,TKey>> order,System.Linq.Expressions.Expression<Func<T,bool>> filter) where T:class{var s=await LoadSourceAsync(id,importId,ct);if(s is null)return NotFound();var importProperty=typeof(T).GetProperty("SaftImportId")??throw new InvalidOperationException();var parameter=System.Linq.Expressions.Expression.Parameter(typeof(T),"x");var predicate=System.Linq.Expressions.Expression.Lambda<Func<T,bool>>(System.Linq.Expressions.Expression.Equal(System.Linq.Expressions.Expression.Property(parameter,importProperty),System.Linq.Expressions.Expression.Constant(s.SelectedImport.Id)),parameter);var q=source.Where(predicate);if(!string.IsNullOrWhiteSpace(search))q=q.Where(filter);return View(new SaftListViewModel<T>{Source=s,List=await PageAsync(q.OrderBy(order),search,page,pageSize,ct)});}
 private async Task<IActionResult> ImportViewAsync(int id,int? importId,CancellationToken ct,Func<IQueryable<SaftImport>,IQueryable<SaftImport>> include){var s=await LoadSourceAsync(id,importId,ct,include);return s is null?NotFound():View(s);}private async Task<SaftImportSelectionViewModel?> LoadSourceAsync(int id,int? importId,CancellationToken ct,Func<IQueryable<SaftImport>,IQueryable<SaftImport>>? include=null){var all=await dbContext.SaftImports.AsNoTracking().Where(x=>x.DossierId==id).OrderByDescending(x=>x.EndDate).ThenByDescending(x=>x.Id).ToListAsync(ct);if(all.Count==0)return null;var selected=importId??all[0].Id;if(!all.Any(x=>x.Id==selected))return null;IQueryable<SaftImport> q=dbContext.SaftImports.AsNoTracking().Include(x=>x.Dossier).ThenInclude(x=>x.AccountingEntity);if(include!=null)q=include(q);var i=await q.SingleOrDefaultAsync(x=>x.Id==selected&&x.DossierId==id,ct);return i is null?null:new(){SelectedImport=i,AvailableImports=all};}
 private static async Task<PagedListViewModel<T>> PageAsync<T>(IQueryable<T> q,string? search,int page,int pageSize,CancellationToken ct){pageSize=AllowedPageSizes.Contains(pageSize)?pageSize:10;page=Math.Max(1,page);var total=await q.CountAsync(ct);var pages=Math.Max(1,(int)Math.Ceiling(total/(double)pageSize));page=Math.Min(page,pages);return new(){Items=await q.Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct),TotalItems=total,Page=page,PageSize=pageSize,Search=search?.Trim()};}private async Task<AnalysisDossier?> LoadDossierAsync(int id,CancellationToken ct)=>await dbContext.AnalysisDossiers.AsNoTracking().Include(x=>x.AccountingEntity).Include(x=>x.Imports).SingleOrDefaultAsync(x=>x.Id==id,ct);
}
